؛ «فم» بمعنى عضو أستخدمه للأكل والتحدث. يفكر الطالب في أمثلة من حياته، ثم يشير إلى الإجابة أو يقرؤها مستعينًا بمعلمه. يمكن للمعلم تكرار النطق بوضوح، ويطلب من الطالب المقارنة قبل الاختيار. هذه المادة إثرائية مستقلة ولا تثبت المطابقة التفصيلية للطبعة الرسمية.","grade":1,"items":[{"sentence":"أكمل: أرسم عينين ثم ___ ثم الفم.","options":["عين","أنف","فم"]}]},"answer":{"answers":["أنف"]}},{"lessonId":"37aeb9a8-72de-4e9d-99d7-20fef2c3ed6e","lessonTitle":"ورقة عمل (40) أرسم وجهي","page":72,"section":"practice","activity_order":6,"activity_type":"matching","title":"أصل الكلمة بمعناها","prompt":"صل الكلمات بمعانيها في نشاط «ورقة عمل (40) أرسم وجهي».","content":{"origin":"DADYOOM_BH_G1_FOUNDATIONAL_LITERACY_25_EXERCISES_20261030","anchor":"عين، أنف، فم.","originalReference":"دعم تعليمي أصلي من ضاديوم للصف الأول في البحرين، درس «ورقة عمل (40) أرسم وجهي». لا ننقل نصًا من الكتاب المدرسي. يقرأ المعلم الكلمات أو يعرض بطاقات عليها: «عين» بمعنى عضو أستعمله للنظر؛ «أنف» بمعنى عضو يساعد على الشم والتنفس؛ «فم» بمعنى عضو أستخدمه للأكل والتحدث. يفكر الطالب في أمثلة من حياته، ثم يشير إلى الإجابة أو يقرؤها مستعينًا بمعلمه. يمكن للمعلم تكرار النطق بوضوح، ويطلب من الطالب المقارنة قبل الاختيار. هذه المادة إثرائية مستقلة ولا تثبت المطابقة التفصيلية للطبعة الرسمية.","grade":1,"left":["عين","أنف","فم"],"right":["عضو أستخدمه للأكل والتحدث","عضو يساعد على الشم والتنفس","عضو أستعمله للنظر"]},"answer":{"pairs":[{"left":"عين","right":"عضو أستعمله للنظر"},{"left":"أنف","right":"عضو يساعد على الشم والتنفس"},{"left":"فم","right":"عضو أستخدمه للأكل والتحدث"}]}}]$batch$::jsonb)
AS x("lessonId" text,"lessonTitle" text,page int,activity_order int,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $safe$ DECLARE expected integer; actual integer;
BEGIN
 IF (SELECT count(*) FROM pg_temp.g1_p25)<>25 OR (SELECT count(DISTINCT lesson_id) FROM pg_temp.g1_p25)<>5
 OR EXISTS(SELECT 1 FROM pg_temp.g1_p25 x WHERE x.activity_order NOT BETWEEN 2 AND 6
 OR x.content ? 'answer' OR x.content ? 'correct'
 OR (x.activity_type='multiple_choice' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(x.content->'options') v WHERE v=x.answer->>'correct'))
 OR (x.activity_type='fill_blank' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(x.content->'items'->0->'options') v WHERE v=x.answer->'answers'->>0))
 OR (x.activity_type='matching' AND jsonb_array_length(x.answer->'pairs')<>jsonb_array_length(x.content->'left')))
 THEN RAISE EXCEPTION 'Invalid Grade1 phonics batch'; END IF;
 SELECT count(DISTINCT l.id) INTO expected FROM public.lessons l
 JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id JOIN public.curricula c ON c.id=g.curriculum_id JOIN public.countries co ON co.id=c.country_id
 JOIN pg_temp.g1_p25 x ON x.lesson_id=l.id AND x.lesson_title=l.title AND x.page=l.source_page_start
 WHERE l.status='published' AND co.code='BH' AND g.grade_number=1 AND l.source_pdf_url IS NOT NULL
 AND position(x.content->>'anchor' IN l.content)>0
 AND (SELECT count(*) FROM public.lesson_activities a WHERE a.lesson_id=l.id AND a.is_published)=1
 AND (SELECT max(activity_order) FROM public.lesson_activities a WHERE a.lesson_id=l.id)=1
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts t JOIN public.lesson_activities a ON a.id=t.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts t JOIN public.questions q ON q.id=t.question_id WHERE q.lesson_id=l.id);
 IF expected<>5 THEN RAISE EXCEPTION 'Source or learner history changed: %/5',expected; END IF;
 IF EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.content->>'origin'='DADYOOM_BH_G1_FOUNDATIONAL_LITERACY_25_EXERCISES_20261030') THEN RAISE EXCEPTION 'Duplicate batch'; END IF;
 INSERT INTO public.lesson_activities(lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
 SELECT x.lesson_id,x.title,x.activity_type,'تعلم أصلي بإرشاد المعلم؛ ثم أجب دون عرض الحل.',x.content,x.activity_order,5,true,x.section,x.prompt,x.answer,false
 FROM pg_temp.g1_p25 x;
 GET DIAGNOSTICS actual=ROW_COUNT;
 IF actual<>25 THEN RAISE EXCEPTION 'Rollback unexpected % activities',actual; END IF;
END $safe$;
COMMIT;